package conformance
import("crypto/sha256";"encoding/hex";"encoding/json";"fmt";"github.com/kakon77777-commits/isql-origin-go/sections";"github.com/kakon77777-commits/isql-origin-go/wire")
type ActionContext struct{Subject,Target,TargetType wire.Ref;SatisfiedGuards,GrantedCapabilities,DeniedCapabilities,AcceptedAuthorities []wire.Ref};type ActionCertificate struct{OriginSHA256 string;Operator wire.Ref;Ready bool;Errors []string;Effects,InvariantObligations []wire.Ref;Executor *wire.Ref;ResourceBound wire.Ref};type DSRHandoff struct{Status string;Execute bool;ArtifactKind string;NativeVersion uint64;NativeSHA256 string;NativeBytes int;Operator,Executor wire.Ref;OriginSHA256 string}
type ctxJSON struct{Subject string `json:"subject_ref"`;Target string `json:"target_ref"`;TargetType string `json:"target_type_ref"`;Satisfied []string `json:"satisfied_guard_refs"`;Granted []string `json:"granted_capabilities"`;Denied []string `json:"denied_capabilities"`;Accepted []string `json:"accepted_authority_refs"`}
func parseRef(s string)(wire.Ref,error){var a,b uint64;if _,e:=fmt.Sscanf(s,"%d:%d",&a,&b);e!=nil{return wire.Ref{},e};return wire.Ref{a,b},nil};func parseRefs(xs []string)([]wire.Ref,error){out:=make([]wire.Ref,0,len(xs));for _,s:=range xs{r,e:=parseRef(s);if e!=nil{return nil,e};out=append(out,r)};return out,nil};func parseContext(raw []byte)(ActionContext,error){var c ctxJSON;if e:=json.Unmarshal(raw,&c);e!=nil{return ActionContext{},e};s,e:=parseRef(c.Subject);if e!=nil{return ActionContext{},e};t,e:=parseRef(c.Target);if e!=nil{return ActionContext{},e};tt,e:=parseRef(c.TargetType);if e!=nil{return ActionContext{},e};sg,e:=parseRefs(c.Satisfied);if e!=nil{return ActionContext{},e};g,e:=parseRefs(c.Granted);if e!=nil{return ActionContext{},e};d,e:=parseRefs(c.Denied);if e!=nil{return ActionContext{},e};a,e:=parseRefs(c.Accepted);if e!=nil{return ActionContext{},e};return ActionContext{s,t,tt,sg,g,d,a},nil};func in(xs []wire.Ref,r wire.Ref)bool{for _,x:=range xs{if x==r{return true}};return false}
func BuildActionCertificate(originRaw []byte,obj wire.OMIR,opRef wire.Ref,contextJSON []byte)(ActionCertificate,error){by:=sectionMap(obj);ops,e:=sections.DecodeOperators(by[4]);if e!=nil{return ActionCertificate{},e};auths,e:=sections.DecodeAuthorities(by[5]);if e!=nil{return ActionCertificate{},e};ctx,e:=parseContext(contextJSON);if e!=nil{return ActionCertificate{},e};var op *sections.Operator;for i:=range ops{if ops[i].Operator==opRef{op=&ops[i];break}};if op==nil{return ActionCertificate{},fmt.Errorf("P3_OPERATOR_NOT_FOUND")};errs:=[]string{};if ctx.TargetType!=op.DomainType{errs=append(errs,"P3_TYPE_MISMATCH")};if op.Guard!=(wire.Ref{0,0})&&!in(ctx.SatisfiedGuards,op.Guard){errs=append(errs,"P3_GUARD_FAILED")};for _,cap:=range op.Capabilities{if !in(ctx.GrantedCapabilities,cap)||in(ctx.DeniedCapabilities,cap){errs=append(errs,fmt.Sprintf("CAPABILITY_DENIED:%s",refText(cap)))}};grants:=map[wire.Ref]bool{};denies:=map[wire.Ref]bool{};for _,a:=range auths{if !in(ctx.AcceptedAuthorities,a.Authority)||a.Subject!=ctx.Subject||a.Scope!=op.Operator{continue};for _,r:=range a.Grants{grants[r]=true};for _,r:=range a.Denies{denies[r]=true}};for _,req:=range op.AuthorityRequirements{if denies[req]{errs=append(errs,fmt.Sprintf("AUTHORITY_DENIED:%s",refText(req)))}else if !grants[req]{errs=append(errs,fmt.Sprintf("AUTHORITY_MISSING:%s",refText(req)))}};h:=sha256.Sum256(originRaw);return ActionCertificate{OriginSHA256:hex.EncodeToString(h[:]),Operator:opRef,Ready:len(errs)==0,Errors:errs,Effects:op.Effects,InvariantObligations:op.InvariantObligations,Executor:op.Executor,ResourceBound:op.ResourceBound},nil}
func PrepareDSRHandoff(cert ActionCertificate,executor []byte)(DSRHandoff,error){if !cert.Ready{return DSRHandoff{},fmt.Errorf("P3_HANDOFF_CERTIFICATE_NOT_READY")};if cert.Executor==nil{return DSRHandoff{},fmt.Errorf("P3_HANDOFF_EXECUTOR_REF_MISSING")};d,e:=DetectNative(executor);if e!=nil{return DSRHandoff{},e};if d.Kind!="dsr.causal-program"&&d.Kind!="dsr.vm-program"{return DSRHandoff{},fmt.Errorf("P3_DSR_EXECUTOR_NOT_PROGRAM")};h:=sha256.Sum256(executor);return DSRHandoff{Status:"READY",Execute:false,ArtifactKind:d.Kind,NativeVersion:d.Version,NativeSHA256:hex.EncodeToString(h[:]),NativeBytes:len(executor),Operator:cert.Operator,Executor:*cert.Executor,OriginSHA256:cert.OriginSHA256},nil}
